import pandas as pd
import re

def words(label):
    return set([w.strip().lower() for w in label.split('|') if w.strip()])

res=pd.read_csv('/root/output/unified_taxonomy_full.csv')
# check overlaps between level1 and level2 labels
pairs = res[['unified_level_1','unified_level_2']].drop_duplicates()
overlaps=[]
for l1,l2 in pairs.values:
    if l2 and l1:
        if words(l1) & words(l2):
            overlaps.append((l1,l2))

print('overlaps l1-l2', len(overlaps))
print(overlaps[:20])
