import pandas as pd

def words(label):
    return set([w.strip().lower() for w in str(label).split('|') if w.strip()])

res=pd.read_csv('/root/output/unified_taxonomy_full.csv')
for p,c in [('unified_level_2','unified_level_3'),('unified_level_3','unified_level_4'),('unified_level_4','unified_level_5')]:
    pairs=res[[p,c]].drop_duplicates()
    overlaps=0
    for parent, child in pairs.values:
        if child and parent:
            if words(parent) & words(child):
                overlaps+=1
    print(p,'->',c,'overlaps',overlaps)
